<?php
use DigiForge\POD\{PersonalizedProductPreparation as Contract,PersonalizedProofRepository as Proofs,Shop2ProductWorkflow};
use DigiForge\Portal\PersonalizedPreparationPanel as Panel;
require_once __DIR__.'/fixtures/PortalAccessFixture.php';require_once __DIR__.'/fixtures/MissionBFixture.php';
final class MissionBPersonalizationTest extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();$_GET=[];global $wpdb;$wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name LIKE %s",$wpdb->esc_like('digiforge_native_proof_').'%'));$wpdb->delete(DigiForge\Database\Tables::audit_log(),['object_type'=>'personalized_proof']);}
 protected function tearDown():void{$_GET=[];global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function prepare(string $f='FL-03'):array {PortalAccessFixture::enroll();$w=MissionBFixture::workflow($f);$r=(new Proofs())->create($w['supplier_workflow_hash'],MissionBFixture::input($f));self::assertNotWPError($r,is_wp_error($r)?$r->get_error_code():'');return [$w,$r];}
 public function testMugAndPosterFromSupplierToImmutableHumanReviewedHeldPreparation():void {
  PortalAccessFixture::enroll();$calls=0;$deny=static function()use(&$calls){++$calls;throw new RuntimeException('No network');};add_filter('pre_http_request',$deny);
  try{foreach(['FL-03','FL-04']as $f){$w=MissionBFixture::workflow($f);$input=MissionBFixture::input($f);$repo=new Proofs();$r=$repo->create($w['supplier_workflow_hash'],$input);self::assertNotWPError($r,is_wp_error($r)?$r->get_error_code():'');$p=$r['record']['prepared'];self::assertSame($input['artwork']['sha256'],$p['production']['fixed_artwork_sha256']);self::assertFalse($p['production']['native_text_rendered_into_production']);self::assertSame(3,substr_count($p['proof_svg'],'<text '));self::assertSame(40,$p['native_bindings'][0]['font_size']);self::assertSame(DigiForge\Listings\Validator::canonicalJson($input['template']),DigiForge\Listings\Validator::canonicalJson($p['template_evidence']));self::assertSame(hash('sha256',$p['proof_svg']),$p['proof_sha256']);self::assertSame('VERIFIED_LOCAL_GEOMETRY',$p['geometry']['state']);self::assertNull($p['production_cost']);self::assertFalse($p['external_execution_authorized']);self::assertWPError($repo->export($r['hash'],'synthetic-line'));self::assertNotWPError($repo->decide($r['hash'],'APPROVE','Synthetic local proof review only'));$out=$repo->export($r['hash'],'synthetic-line');self::assertNotWPError($out);self::assertFalse($out['production_submit_ready']);self::assertFalse($out['etsy_publish_ready']);self::assertSame('BLOCKED',$out['state']);self::assertContains('PROVIDER_UNVERIFIED',$out['remaining_gates']);self::assertNotContains('HUMAN_APPROVAL_REQUIRED',$out['remaining_gates']);self::assertSame($r['hash'],$repo->create($w['supplier_workflow_hash'],$input)['hash']);self::assertWPError($repo->decide($r['hash'],'REJECT','Cannot overwrite an immutable decision'));}}finally{remove_filter('pre_http_request',$deny);}self::assertSame(0,$calls);
 }
 public function testRejectionAndCorrectionProduceDifferentImmutableProofs():void {[$w,$r]=$this->prepare();$repo=new Proofs();self::assertNotWPError($repo->decide($r['hash'],'REJECT','Correct customer text'));self::assertWPError($repo->export($r['hash'],'line'));$i=MissionBFixture::input();$i['values']['name_one']='Taylor';$child=$repo->create($w['supplier_workflow_hash'],$i,$r['hash']);self::assertNotWPError($child);self::assertNotSame($r['hash'],$child['hash']);self::assertSame($r['hash'],$child['record']['parent']);self::assertWPError($repo->export($child['hash'],'line'));}
 public function testTypedInputsMappingDoublePrintGeometryAndProviderMismatchFailClosed():void {[$w,$r]=$this->prepare();$link=(new Shop2ProductWorkflow())->read($w['supplier_workflow_hash']);$base=MissionBFixture::input();$mutations=[static function(&$x){$x['values']['name_one']=str_repeat('X',14);},static function(&$x){unset($x['values']['name_two']);},static function(&$x){$x['values']['unknown']='bad';},static function(&$x){$x['values']['name_one']="bad\nname";},static function(&$x){$x['artwork']['native_text_embedded']=true;},static function(&$x){$x['template']['layers'][1]['layer_id']=$x['template']['layers'][0]['layer_id'];},static function(&$x){$x['template']['layers'][1]['field']=$x['template']['layers'][0]['field'];},static function(&$x){$x['template']['layers'][0]['x']=0;},static function(&$x){$x['template']['provider_id']=99;},static function(&$x){$x['template']['dpi']=72;},static function(&$x){$x['artwork']['sha256']=str_repeat('f',64);}];foreach($mutations as $mutate){$i=$base;$mutate($i);try{Contract::prepare($i,$link['review']);self::fail('Invalid metadata accepted');}catch(InvalidArgumentException){self::assertTrue(true);}}}
 public function testMissingGeometryAndR4StayExplicitlyUnverifiedAndTextEscapes():void {[$w]=$this->prepare();$link=(new Shop2ProductWorkflow())->read($w['supplier_workflow_hash']);$i=MissionBFixture::input();unset($i['template']['qa_geometry']);$i['values']['name_one']='A&B <X>';$p=Contract::prepare($i,$link['review']);self::assertContains('SAFE_AREA_GEOMETRY_MISSING',$p['remaining_gates']);self::assertContains('QUALIFIED_R4_SOURCE_REVIEW_REQUIRED',$p['remaining_gates']);self::assertStringContainsString('A&amp;B &lt;X&gt;',$p['proof_svg']);self::assertStringNotContainsString('<X>',$p['proof_svg']);}
 public function testScopedPanelRequiresNonceAndViewerCannotPrepareOrReview():void {[$w,$r]=$this->prepare();$panel=new Panel();$p=['shop_key'=>'personalized_pod','operation'=>'review','proof'=>$r['hash'],'decision'=>'APPROVE','note'=>'local','confirm'=>'LOCAL_PROOF_ONLY'];self::assertWPError($panel->process($p));$p['_wpnonce']=wp_create_nonce(Panel::ACTION);$p['shop_key']='digital';self::assertWPError($panel->process($p));$id=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($id);self::assertWPError((new Proofs())->read($r['hash']));self::assertWPError((new Proofs())->decide($r['hash'],'APPROVE','wrong actor'));$_GET=['df_view'=>'pod_personalized','df_shop'=>'digital'];self::assertSame('unchanged',$panel->render('unchanged','digiforge_admin_portal',[],[]));}
 public function testTamperingAndMissingAuditEvidenceBlockExports():void {[$w,$r]=$this->prepare();global $wpdb;$repo=new Proofs();self::assertNotWPError($repo->decide($r['hash'],'APPROVE','local'));$wpdb->delete(DigiForge\Database\Tables::audit_log(),['object_type'=>'personalized_proof','object_id'=>$r['hash'],'event_type'=>'personalized_proof_reviewed']);self::assertWPError($repo->export($r['hash'],'line'));self::assertSame('UNVERIFIED',$repo->queue()[0]['review_state']);$wpdb->update($wpdb->options,['option_value'=>'{}'],['option_name'=>'digiforge_native_proof_'.$r['hash']]);self::assertWPError($repo->read($r['hash']));}
 public function testProviderPlanUsesExistingReadContractWithoutCredentialsReservationsOrWrites():void {[$w,$r]=$this->prepare();$repo=new Proofs();self::assertNotWPError($repo->decide($r['hash'],'APPROVE','Synthetic local review'));$i=(new DigiForge\Integrations\Repository())->create(['provider'=>'printify','environment'=>'test','connection_key'=>'mission-b-'.wp_generate_uuid4(),'display_name'=>'Synthetic metadata only','status'=>'CONFIGURED','enabled'=>false,'config'=>['shop_key'=>'personalized_pod','shop_id'=>'12','account_reference'=>'fixture']]);self::assertNotWPError($i);global $wpdb;$before=(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DigiForge\Database\Tables::idempotency());$plan=(new DigiForge\POD\PersonalizedPrintifyPreparation())->plan($r['hash'],(int)$i['id'],'synthetic-line');self::assertNotWPError($plan,is_wp_error($plan)?$plan->get_error_code():'');self::assertSame('GET',$plan['readback_request']['method']);self::assertStringContainsString('/v1/shops/12/products/6ae98d61eb5d7e24b80ca0a6.json',$plan['readback_request']['endpoint']);self::assertFalse($plan['order_submission_permitted']);self::assertFalse($plan['product_save_permitted']);self::assertFalse($plan['product_create_permitted']);self::assertSame('UNVERIFIED',$plan['connection_state']);self::assertContains('EXACT_REVIEWED_PROVIDER_CONNECTION_REQUIRED',$plan['remaining_gates']);self::assertSame($before,(int)$wpdb->get_var('SELECT COUNT(*) FROM '.DigiForge\Database\Tables::idempotency()));self::assertSame($plan['correlation_reference'],(new DigiForge\POD\PersonalizedPrintifyPreparation())->plan($r['hash'],(int)$i['id'],'synthetic-line')['correlation_reference']);}
 public function testFailedAuditRollsBackProofAndCannotFabricateReadiness():void {PortalAccessFixture::enroll();$w=MissionBFixture::workflow('FL-03');global $wpdb;$filter=static function($sql){return str_starts_with($sql,'INSERT')&&str_contains($sql,'personalized_proof_prepared')?'INSERT INTO missing_missionb_audit VALUES (1)':$sql;};$before=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_native_proof_%'");add_filter('query',$filter);$old=$wpdb->suppress_errors(true);try{$r=(new Proofs())->create($w['supplier_workflow_hash'],MissionBFixture::input());}finally{remove_filter('query',$filter);$wpdb->suppress_errors($old);}self::assertWPError($r);self::assertSame($before,(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE 'digiforge_native_proof_%'"));}
 public function testViewerDelegationCannotUseProofControlsAndOtherShopHasNoMount():void {[$w,$r]=$this->prepare();$id=self::factory()->user->create(['role'=>'administrator']);$changed=DigiForge\PortalAccess\Store::change($id,'Viewer',['personalized_pod'=>['personalized_pod','products','research','listings']],true,0,wp_generate_uuid4());self::assertNotWPError($changed);PortalAccessFixture::login($id);self::assertNotWPError(DigiForge\PortalAccess\Session::start());self::assertWPError((new Proofs())->read($r['hash']));$_GET=['df_shop'=>'digital','df_view'=>'pod_personalized'];self::assertSame('Digital unchanged',(new Panel())->render('Digital unchanged','digiforge_admin_portal',[],[]));}
 public function testPortalProofQueueAndExactConfirmationControlsRenderOnlyForShop2():void {[$w,$r]=$this->prepare();$_GET=['df_view'=>'pod_personalized','df_shop'=>'personalized_pod','df_proof'=>$r['hash']];$h=(new Panel())->render('Existing portal','digiforge_admin_portal',[],[]);foreach(['Existing portal','Customer personalization','Proof review queue','LOCAL_PROOF_ONLY','Export held preparation','No artwork rebuild']as $text){if($text==='No artwork rebuild')continue;self::assertStringContainsString($text,$h);}self::assertStringContainsString('data:image/svg+xml;base64,',$h);self::assertStringNotContainsString('api_key',$h);}
 public function testCalendarInputsCredentialsAndRetainedProviderGeometryConflictsFailClosed():void {[$w]=$this->prepare();$link=(new Shop2ProductWorkflow())->read($w['supplier_workflow_hash']);$i=MissionBFixture::input();$i['template']['fields'][2]['type']='date';$i['values']['occasion']='2026-02-28';self::assertSame('2026-02-28',Contract::prepare($i,$link['review'])['native_bindings'][2]['value']);$i['values']['occasion']='2026-02-30';try{Contract::prepare($i,$link['review']);self::fail('Invalid calendar date');}catch(InvalidArgumentException){self::assertTrue(true);} $i=MissionBFixture::input();$i['template']['api_key']='never-store';try{Contract::prepare($i,$link['review']);self::fail('Credential keys');}catch(InvalidArgumentException){self::assertTrue(true);} $i=MissionBFixture::input();$link['review']['evidence']['print_areas'][0]['facts']['Width PX']='100';try{Contract::prepare($i,$link['review']);self::fail('Conflicting provider geometry');}catch(InvalidArgumentException){self::assertTrue(true);}}
 public function testNativeTextEditingCreatesNewUnapprovedChildWithoutChangingApprovedProof():void {[$w,$r]=$this->prepare();$repo=new Proofs();self::assertNotWPError($repo->decide($r['hash'],'APPROVE','original local proof'));$child=$repo->personalize($r['hash'],['name_one'=>'Robin','name_two'=>'Casey','occasion'=>'June 9, 2026']);self::assertNotWPError($child);self::assertNotSame($r['hash'],$child['hash']);self::assertSame($r['hash'],$child['record']['parent']);self::assertSame($r['record']['prepared']['template_sha256'],$child['record']['prepared']['template_sha256']);self::assertSame($r['record']['prepared']['artwork_sha256'],$child['record']['prepared']['artwork_sha256']);self::assertWPError($repo->export($child['hash'],'line'));self::assertNotWPError($repo->export($r['hash'],'line'));$_GET=['df_view'=>'pod_personalized','df_shop'=>'personalized_pod','df_proof'=>$child['hash']];$h=(new Panel())->render('','digiforge_admin_portal',[],[]);self::assertStringContainsString('values[name_one]',$h);self::assertStringContainsString('maxlength="13"',$h);self::assertStringContainsString('Create new customer proof version',$h);}
}
